        const done = reachedStep >= index;
        const current = order.status === step.key;
        const Icon = index === 0 ? Check : index === 1 ? Truck : Package;
        return <div className={`order-timeline-step${done ? " done" : ""}${current ? " current" : ""}`} key={step.key}>
